"use strict";
// Love Letter (2-4 players), standard rules, one combined play per turn.
// Deck of 16: Guard(1)x5, Priest(2)x2, Baron(3)x2, Handmaid(4)x2,
// Prince(5)x2, King(6)x1, Countess(7)x1, Princess(8)x1.
// State keeps the deck as an explicit card array, so drawing is a
// deterministic pop; only shuffling (newMatch and a new round) uses
// ctx.random(). The player to move always holds 2 cards in state: the
// draw at the start of their turn happens when the turn advances to
// them (and in setup for the round starter).
const DECK_SPEC = [[1,5],[2,2],[3,2],[4,2],[5,2],[6,1],[7,1],[8,1]];
function buildDeck(ctx) {
  const d = [];
  for (const pair of DECK_SPEC) for (let i = 0; i < pair[1]; i++) d.push(pair[0]);
  for (let i = d.length - 1; i > 0; i--) {
    const j = Math.floor(ctx.random() * (i + 1));
    const t = d[i]; d[i] = d[j]; d[j] = t;
  }
  return d;
}
function tokensNeededFor(n) { return n === 2 ? 7 : n === 3 ? 5 : 4; }
function copyState(s) { return JSON.parse(JSON.stringify(s)); }
function clearSeenColumn(s, seat) { for (let i = 0; i < s.lastSeen.length; i++) s.lastSeen[i][seat] = 0; }
function setupRound(s, ctx, starter) {
  const n = ctx.players.length;
  const deck = buildDeck(ctx);
  s.removedDown = [deck.pop()];
  s.removedUp = [];
  if (n === 2) s.removedUp = [deck.pop(), deck.pop(), deck.pop()];
  s.hands = []; s.discards = []; s.active = []; s.protected = []; s.lastSeen = [];
  for (let i = 0; i < n; i++) {
    s.hands.push([deck.pop()]); s.discards.push([]);
    s.active.push(true); s.protected.push(false); s.lastSeen.push(Array(n).fill(0));
  }
  s.deck = deck; s.starter = starter; s.turn = starter;
  s.hands[starter].push(s.deck.pop());
}
function eliminate(s, seat) {
  s.active[seat] = false; s.protected[seat] = false;
  for (const c of s.hands[seat]) s.discards[seat].push(c);
  s.hands[seat] = [];
  clearSeenColumn(s, seat);
  for (let i = 0; i < s.lastSeen.length; i++) s.lastSeen[seat][i] = 0;
}
function legalMoves(s, ctx) {
  if (s.over) return [];
  const seat = s.turn, hand = s.hands[seat];
  if (!hand || !hand.length) return [];
  const ids = ctx.players.map(p => p.id);
  const mustCountess = hand.indexOf(7) !== -1 && (hand.indexOf(6) !== -1 || hand.indexOf(5) !== -1);
  const distinct = [];
  for (const c of hand) if (distinct.indexOf(c) === -1) distinct.push(c);
  const cards = mustCountess ? [7] : distinct;
  const others = [];
  for (let i = 0; i < s.hands.length; i++)
    if (i !== seat && s.active[i] && !s.protected[i]) others.push(i);
  const out = [];
  for (const c of cards) {
    if (c === 1) {
      if (!others.length) out.push({type:'play', card:1, target:null, guess:null});
      else for (const t of others) for (let g = 2; g <= 8; g++)
        out.push({type:'play', card:1, target:ids[t], guess:g});
    } else if (c === 2 || c === 3 || c === 6) {
      if (!others.length) out.push({type:'play', card:c, target:null, guess:null});
      else for (const t of others) out.push({type:'play', card:c, target:ids[t], guess:null});
    } else if (c === 5) {
      for (const t of others) out.push({type:'play', card:5, target:ids[t], guess:null});
      out.push({type:'play', card:5, target:ids[seat], guess:null});
      if (!others.length) out.push({type:'play', card:5, target:null, guess:null});
    } else {
      out.push({type:'play', card:c, target:null, guess:null});
    }
  }
  return out;
}
function payoutFor(s, ctx) {
  if (!ctx.pot) return {};
  const humans = ctx.players.filter(p => p.kind === 'human' && p.active !== false);
  const w = ctx.players[s.winner];
  const recips = w && w.kind === 'human' && w.active !== false ? [w] : humans;
  const out = {};
  if (!recips.length) return out;
  recips.forEach((p, i) => { out[p.id] = Math.floor(ctx.pot / recips.length) + (i < ctx.pot % recips.length ? 1 : 0); });
  return out;
}
function endRound(s, ctx, winners) {
  for (const w of winners) s.tokens[w]++;
  let champ = -1;
  for (let i = 0; i < s.tokens.length; i++)
    if (s.tokens[i] >= s.tokensNeeded && (champ === -1 || s.tokens[i] > s.tokens[champ])) champ = i;
  if (champ >= 0) {
    s.over = true; s.winner = champ; s.lastRoundWinners = winners.slice();
    return {state:s, turn:null, payouts:payoutFor(s, ctx)};
  }
  const starter = winners[0], round = s.round + 1;
  setupRound(s, ctx, starter);
  s.round = round; s.lastRoundWinners = winners.slice();
  return {state:s, turn:[ctx.players[starter].id]};
}
const game = {
  newMatch(ctx) {
    const n = ctx.players.length;
    const s = {hands:[], deck:[], removedDown:[], removedUp:[], discards:[],
      tokens:Array(n).fill(0), active:[], protected:[], turn:0, round:1,
      starter:0, tokensNeeded:tokensNeededFor(n), winner:-1, over:false,
      lastRoundWinners:[], lastSeen:[], turns:0, lastMove:null};
    setupRound(s, ctx, 0);
    return {state:s, turn:[ctx.players[0].id]};
  },
  applyMove(state, id, move, ctx) {
    if (state.over) throw new InvalidMove('Illegal move');
    const seat = ctx.players.findIndex(p => p.id === id);
    if (seat < 0 || seat !== state.turn) throw new InvalidMove('Illegal move');
    if (!move || typeof move !== 'object' || Array.isArray(move)) throw new InvalidMove('Illegal move');
    const opts = legalMoves(state, ctx);
    const ok = Object.keys(move).length === 4 && opts.some(m =>
      m.type === move.type && m.card === move.card && m.target === move.target && m.guess === move.guess);
    if (!ok) throw new InvalidMove('Illegal move');
    const s = copyState(state); s.turns++;
    const A = seat, card = move.card;
    const T = move.target === null ? -1 : ctx.players.findIndex(p => p.id === move.target);
    const fromIndex = s.hands[A].indexOf(card);
    const prevDisc = s.discards.map(d => d.length);
    s.hands[A].splice(fromIndex, 1);
    s.discards[A].push(card);
    clearSeenColumn(s, A);
    if (card === 1 && T >= 0) {
      if (s.hands[T].length && s.hands[T][0] === move.guess) eliminate(s, T);
    } else if (card === 2 && T >= 0) {
      if (s.hands[T].length) s.lastSeen[A][T] = s.hands[T][0];
    } else if (card === 3 && T >= 0) {
      const a = s.hands[A][0], b = s.hands[T][0];
      if (a !== undefined && b !== undefined) {
        s.lastSeen[A][T] = b; s.lastSeen[T][A] = a;
        if (a < b) eliminate(s, A); else if (b < a) eliminate(s, T);
      }
    } else if (card === 4) {
      s.protected[A] = true;
    } else if (card === 5 && T >= 0) {
      const discarded = s.hands[T].length ? s.hands[T][0] : null;
      if (discarded !== null) {
        s.discards[T].push(discarded); s.hands[T] = []; clearSeenColumn(s, T);
        if (discarded === 8) eliminate(s, T);
        else {
          let nc = null;
          if (s.deck.length) nc = s.deck.pop();
          else if (s.removedDown.length) nc = s.removedDown.pop();
          if (nc !== null) s.hands[T] = [nc];
        }
      }
    } else if (card === 6 && T >= 0) {
      const tmp = s.hands[A]; s.hands[A] = s.hands[T]; s.hands[T] = tmp;
      clearSeenColumn(s, A); clearSeenColumn(s, T);
    } else if (card === 8) {
      eliminate(s, A);
    }
    const extras = [];
    for (let i = 0; i < s.discards.length; i++) {
      const start = prevDisc[i] + (i === A ? 1 : 0);
      for (let k = start; k < s.discards[i].length; k++)
        extras.push({seat:i, card:s.discards[i][k], index:k});
    }
    const alive = [];
    for (let i = 0; i < s.hands.length; i++) if (s.active[i]) alive.push(i);
    if (alive.length === 1) { const r = endRound(s, ctx, [alive[0]]); r.state.lastMove = {kind:'round'}; return r; }
    if (s.deck.length === 0) {
      const val = i => s.hands[i].length ? s.hands[i][0] : 0;
      let best = -1;
      for (const i of alive) best = Math.max(best, val(i));
      let tied = alive.filter(i => val(i) === best);
      if (tied.length > 1) {
        const sum = i => s.discards[i].reduce((x, y) => x + y, 0);
        let bs = -1;
        for (const i of tied) bs = Math.max(bs, sum(i));
        tied = tied.filter(i => sum(i) === bs);
      }
      const r = endRound(s, ctx, tied); r.state.lastMove = {kind:'round'}; return r;
    }
    let nx = A;
    do { nx = (nx + 1) % s.hands.length; } while (!s.active[nx]);
    s.turn = nx; s.protected[nx] = false;
    let drawnIndex = -1;
    if (s.deck.length) { s.hands[nx].push(s.deck.pop()); drawnIndex = s.hands[nx].length - 1; }
    s.lastMove = {kind:'play', actor:A, card:card, fromIndex:fromIndex,
      playedIndex:prevDisc[A], extras:extras,
      drawer:drawnIndex >= 0 ? nx : null, drawnIndex:drawnIndex};
    return {state:s, turn:[ctx.players[nx].id]};
  },
  viewFor(state, id, ctx) {
    const seat = id === null || id === undefined ? -1 : ctx.players.findIndex(p => p.id === id);
    const n = state.hands.length;
    return {
      myIndex: seat,
      playerIds: ctx.players.map(p => p.id),
      myHand: seat >= 0 ? state.hands[seat].slice() : [],
      handCounts: state.hands.map(h => h.length),
      deckCount: state.deck.length,
      removedUp: state.removedUp.slice(),
      removedDownCount: state.removedDown.length,
      discards: state.discards.map(d => d.slice()),
      tokens: state.tokens.slice(),
      active: state.active.slice(),
      protected: state.protected.slice(),
      turn: state.turn, round: state.round, starter: state.starter,
      tokensNeeded: state.tokensNeeded, winner: state.winner, over: state.over,
      lastRoundWinners: state.lastRoundWinners.slice(),
      seen: seat >= 0 ? state.lastSeen[seat].slice() : Array(n).fill(0),
      last_move: state.lastMove ? JSON.parse(JSON.stringify(state.lastMove)) : null,
      legal: seat >= 0 && seat === state.turn && !state.over ? legalMoves(state, ctx) : []
    };
  },
  randomMove(s, id, ctx) {
    const opts = legalMoves(s, ctx);
    return opts[Math.floor(ctx.random() * opts.length)];
  },
  computerMove(s, id, ctx) {
    const seat = s.turn, opts = legalMoves(s, ctx);
    const remaining = s.hands[seat].filter(c => true);
    const otherCard = c => { const h = s.hands[seat].slice(); h.splice(h.indexOf(c), 1); return h[0]; };
    let best = opts[0], bestScore = -Infinity;
    for (const m of opts) {
      const rest = otherCard(m.card);
      let score = 0;
      if (m.card === 8) score = -100;
      else if (m.card === 1) {
        const ts = m.target === null ? -1 : ctx.players.findIndex(p => p.id === m.target);
        score = ts >= 0 && s.lastSeen[seat][ts] >= 2 && m.guess === s.lastSeen[seat][ts] ? 50 : 6;
      }
      else if (m.card === 2) score = 11;
      else if (m.card === 3) score = rest >= 4 ? 20 + rest : 2;
      else if (m.card === 4) score = 12;
      else if (m.card === 5) {
        const self = m.target === ctx.players[seat].id;
        score = self ? (rest === 8 ? -90 : 4) : 9;
      }
      else if (m.card === 6) score = rest === 8 ? -80 : 10 - rest;
      else if (m.card === 7) score = 7;
      if (score > bestScore) { bestScore = score; best = m; }
    }
    return best;
  }
};

