const SOURCE_STRINGS={"title": "Love Letter", "turn": "Player {n} to play", "your_turn": "Your turn, Player {n}", "finished": "Finished", "winner": "Player {n} wins the match", "round": "Round {n}", "deck": "Deck {n}", "tokens": "Tokens {n}", "you": "You", "opp": "Player {n}", "protected": "Protected", "out": "Out", "removed": "Removed face up", "seen": "Seen: Player {n} holds {v}", "hint_card": "Tap a card to play it", "hint_target": "Tap a target player", "hint_guess": "Choose your Guard guess", "cancel": "Cancel", "play_target": "Target Player {n}", "target_self": "Target yourself", "no_target": "Play with no target", "guess": "Guess {v}", "card_1": "1 Guard", "card_2": "2 Priest", "card_3": "3 Baron", "card_4": "4 Handmaid", "card_5": "5 Prince", "card_6": "6 King", "card_7": "7 Countess", "card_8": "8 Princess", "name_2": "Priest", "name_3": "Baron", "name_4": "Handmaid", "name_5": "Prince", "name_6": "King", "name_7": "Countess", "name_8": "Princess", "server_invalid": "Illegal move"};
const gameUI={
  reduce(message,localState){
    const m=message.type==='ui_event'?message.state_changed:message;
    const s=m.view||m.state||{};
    const strings=Object.assign({},SOURCE_STRINGS,m.strings||{});
    const t=(key,args)=>(strings[key]||key).replace(/\{(\w+)\}/g,(_,k)=>String((args||{})[k]===undefined?'':(args||{})[k]));
    const seat=Number.isInteger(s.myIndex)?s.myIndex:-1;
    const legal=(m.status==='ongoing'&&!m.replay&&m.acting_for_player_index!==null&&m.acting_for_player_index!==undefined&&m.acting_for_player_index===seat&&Array.isArray(s.legal))?s.legal:[];
    const active=legal.length>0;
    const n=(s.handCounts||[]).length;
    const cardText=v=>t('card_'+v);
    let sel=null;
    if(active&&localState&&localState.mc===m.move_count&&localState.viewer===seat&&Number.isInteger(localState.card)){
      const c=localState.card;
      if(legal.some(mv=>mv.card===c)){
        sel={card:c,target:(typeof localState.target==='string'?localState.target:null)};
        if(sel.target!==null&&!legal.some(mv=>mv.card===c&&mv.target===sel.target)) sel.target=null;
      }
    }
    let makeMove=null;
    if(message.type==='ui_event'&&active&&message.event&&message.event.type==='tap'){
      const eid=String(message.event.id||'');
      if(eid.indexOf('hand_')===0){
        const v=parseInt(eid.slice(5),10);
        const movesC=legal.filter(mv=>mv.card===v);
        if(movesC.length===1&&movesC[0].target===null&&movesC[0].guess===null) makeMove=movesC[0];
        else if(movesC.length) sel={card:v,target:null};
      } else if(eid.indexOf('tgt_')===0&&sel){
        const ts=parseInt(eid.slice(4),10);
        const tid=(s.playerIds||[])[ts];
        const cand=legal.filter(mv=>mv.card===sel.card&&mv.target===tid);
        if(cand.length===1) makeMove=cand[0];
        else if(cand.length>1) sel={card:sel.card,target:tid};
      } else if(eid.indexOf('guess_')===0&&sel&&sel.target!==null){
        const g=parseInt(eid.slice(6),10);
        const mv=legal.find(mv=>mv.card===sel.card&&mv.target===sel.target&&mv.guess===g);
        if(mv) makeMove=mv;
      } else if(eid==='notarget'&&sel){
        const mv=legal.find(mv=>mv.card===sel.card&&mv.target===null&&mv.guess===null);
        if(mv) makeMove=mv;
      } else if(eid==='cancel'){
        sel=null;
      }
    }
    const pieces=[],targets=[],controls=[],labels=[];
    labels.push({id:'title',text:t('title'),x:24,y:14,font_size:26});
    labels.push({id:'info',text:t('round',{n:s.round})+' - '+t('deck',{n:s.deckCount}),x:470,y:20,font_size:15});
    let status;
    if(s.over) status=s.winner>=0?t('winner',{n:s.winner+1}):t('finished');
    else status=active?t('your_turn',{n:seat+1}):t('turn',{n:(s.turn||0)+1});
    labels.push({id:'status',text:status,x:24,y:48,font_size:18});
    const rows=[];
    for(let i=0;i<n;i++) if(i!==seat) rows.push(i);
    rows.forEach((pi,ri)=>{
      const y=86+ri*124;
      let txt=t('opp',{n:pi+1})+' - '+t('tokens',{n:(s.tokens||[])[pi]});
      if((s.protected||[])[pi]) txt+=' - '+t('protected');
      if(!(s.active||[])[pi]) txt+=' - '+t('out');
      labels.push({id:'name_'+pi,text:txt,x:24,y:y,font_size:16});
      for(let j=0;j<((s.handCounts||[])[pi]||0);j++)
        pieces.push({id:'back_'+pi+'_'+j,type:'back',board:'table',position:{x:30+j*70,y:y+24},text:'',actions:[]});
      ((s.discards||[])[pi]||[]).slice(-8).forEach((v,j)=>
        pieces.push({id:'disc_'+pi+'_'+j,type:'mini',board:'table',position:{x:230+j*44,y:y+30},text:cardText(v),actions:[]}));
    });
    if(seat>=0){
      let txt=t('you')+' - '+t('tokens',{n:(s.tokens||[])[seat]});
      if((s.protected||[])[seat]) txt+=' - '+t('protected');
      if(!(s.active||[])[seat]) txt+=' - '+t('out');
      labels.push({id:'you',text:txt,x:24,y:520,font_size:17});
      ((s.discards||[])[seat]||[]).slice(-8).forEach((v,j)=>
        pieces.push({id:'mydisc_'+j,type:'mini',board:'table',position:{x:24+j*44,y:548},text:cardText(v),actions:[]}));
      if((s.removedUp||[]).length){
        labels.push({id:'removed_label',text:t('removed'),x:480,y:520,font_size:13});
        s.removedUp.forEach((v,j)=>
          pieces.push({id:'rem_'+j,type:'mini',board:'table',position:{x:480+j*44,y:548},text:cardText(v),actions:[]}));
      }
      (s.myHand||[]).forEach((v,i)=>
        pieces.push({id:'handp_'+i,type:'card',board:'table',position:{x:170+i*140,y:640},text:cardText(v),actions:[]}));
      const seenParts=[];
      (s.seen||[]).forEach((v,i)=>{ if(v&&i!==seat) seenParts.push(t('seen',{n:i+1,v:cardText(v)})); });
      if(seenParts.length) labels.push({id:'seen',text:seenParts.join(' - '),x:24,y:614,font_size:14});
    }
    pieces.push({id:'deck_pile',type:'stock',board:'table',position:{x:600,y:640},count:s.deckCount||0,actions:[]});
    if(active){
      const handVals=[];
      legal.forEach(mv=>{ if(handVals.indexOf(mv.card)===-1) handVals.push(mv.card); });
      handVals.forEach(v=>{
        const idx=(s.myHand||[]).indexOf(v);
        targets.push({id:'hand_'+v,board:'table',position:{x:170+(idx>=0?idx:0)*140,y:640},label:cardText(v)});
      });
      if(sel){
        const tids=[];
        legal.filter(mv=>mv.card===sel.card).forEach(mv=>{ if(mv.target!==null&&tids.indexOf(mv.target)===-1) tids.push(mv.target); });
        tids.forEach(tid=>{
          const ts=(s.playerIds||[]).indexOf(tid);
          if(ts===seat) targets.push({id:'tgt_'+ts,board:'table',position:{x:470,y:660},label:t('target_self')});
          else {
            const ri=rows.indexOf(ts);
            targets.push({id:'tgt_'+ts,board:'table',position:{x:610,y:86+(ri>=0?ri:0)*124+40},label:t('play_target',{n:ts+1})});
          }
        });
        if(legal.some(mv=>mv.card===sel.card&&mv.target===null))
          controls.push({id:'notarget',kind:'button',label:t('no_target')});
        if(sel.card===1&&sel.target!==null)
          legal.filter(mv=>mv.card===1&&mv.target===sel.target).forEach(mv=>
            controls.push({id:'guess_'+mv.guess,kind:'button',label:t('guess',{v:t('name_'+mv.guess)})}));
        controls.push({id:'cancel',kind:'button',label:t('cancel')});
        labels.push({id:'hint',text:(sel.card===1&&sel.target!==null)?t('hint_guess'):t('hint_target'),x:330,y:48,font_size:14});
      } else {
        labels.push({id:'hint',text:t('hint_card'),x:330,y:48,font_size:14});
      }
    }
    const scene={pieces:pieces,targets:targets,controls:controls,labels:labels};
    const out={scene:scene,local_state:sel?{mc:m.move_count,viewer:seat,card:sel.card,target:sel.target}:{}};
    if(makeMove) out.make_move=makeMove;
    return out;
  },
  getLastMoveAnimations(view,scene){
    if(!view||!Object.prototype.hasOwnProperty.call(view,'last_move')) return null;
    const lm=view.last_move;
    if(!lm||lm.kind!=='play') return [];
    const seat=Number.isInteger(view.myIndex)?view.myIndex:-1;
    const byId={};
    ((scene&&scene.pieces)||[]).forEach(p=>{ byId[p.id]=p; });
    const rowOf=pi=>{ if(seat<0) return pi; return pi<seat?pi:pi-1; };
    const handPos=(pi,idx)=>{
      if(pi===seat) return {x:170+idx*140,y:640};
      return {x:30+idx*70,y:86+rowOf(pi)*124+24};
    };
    const discId=(pi,fullIdx)=>{
      const total=((view.discards||[])[pi]||[]).length;
      const j=fullIdx-Math.max(0,total-8);
      return j<0?null:(pi===seat?'mydisc_'+j:'disc_'+pi+'_'+j);
    };
    const out=[];
    const add=(pid,src,dur)=>{
      const piece=pid?byId[pid]:null;
      if(!piece) return;
      out.push({piece_id:pid,duration_ms:dur,path:[{board:'table',position:src},{board:piece.board,position:piece.position}]});
    };
    add(discId(lm.actor,lm.playedIndex),handPos(lm.actor,lm.fromIndex||0),600);
    (lm.extras||[]).forEach(ex=>{ add(discId(ex.seat,ex.index),handPos(ex.seat,0),600); });
    if(lm.drawer!==null&&lm.drawer!==undefined&&Number.isInteger(lm.drawnIndex)&&lm.drawnIndex>=0){
      const pid=lm.drawer===seat?'handp_'+lm.drawnIndex:'back_'+lm.drawer+'_'+lm.drawnIndex;
      add(pid,{x:600,y:640},500);
    }
    return out;
  }
};
